 static void requirePlanningWorker(){if(android.os.Looper.myLooper()==android.os.Looper.getMainLooper())throw new IllegalStateException("조회 목록 작업은 백그라운드에서 실행해야 합니다.");}
 CollectionPlan snapshotCollectionPlan(String region)throws Exception{boolean oz=isAsiana();LocalDate today=Search.today();return new CollectionPlan(code(batchOrigin),region,oz,catalog().toString(),today,Search.lastDate(oz,today),System.currentTimeMillis());}
 JSONArray buildCollectionPlan(CollectionPlan plan)throws Exception{
  requirePlanningWorker();JSONObject catalog=new JSONObject(plan.catalogJson);
  if(!plan.asiana){if(plan.region==null)return RegionBatch.all(plan.origin,catalog,plan.today,plan.startedAt);JSONObject batch=RegionBatch.create(plan.origin,plan.region,catalog,plan.today,plan.startedAt,plan.limit,"KE");return batch.getJSONArray("queries").length()==0?new JSONArray():new JSONArray().put(batch);}
  JSONArray selected=new JSONArray();JSONObject regions=catalog.getJSONObject("regions");for(String region:ScanSchedule.REGIONS)if((plan.region==null||plan.region.equals(region))&&regions.has(region)&&regions.getJSONArray(region).length()>0)selected.put(region);
  JSONObject config=new JSONObject().put("enabled",true).put("hour",9).put("minute",10).put("origin",plan.origin).put("KE",new JSONArray()).put("OZ",selected);
  return ScanSchedule.eligibleBatches(config,catalog,catalog,plan.today,plan.startedAt);
 }
 void saveBatches(JSONArray batches)throws Exception{requirePlanningWorker();try(SkyDb metadata=new SkyDb(getApplicationContext())){android.database.sqlite.SQLiteDatabase store=metadata.getWritableDatabase();store.beginTransaction();try{for(int i=0;i<batches.length();i++){if(planningClosed||Thread.currentThread().isInterrupted())throw new InterruptedException("조회 목록 준비가 취소되었습니다.");metadata.batch(batches.getJSONObject(i));}store.setTransactionSuccessful();}finally{store.endTransaction();}}}
 void collectionPreparingUi(){if(content!=null)collectionButtonsEnabled(content,!preparingCollection);if(remoteStatus!=null&&!syncing)remoteStatus.setText(preparingCollection?(preparingRegion==null?"전체 조회 목록 준비 중…":"지역 조회 목록 준비 중…"):Dashboard.remoteMessage(this));}
