 void collectionPlanningFailed(String region,String detail){Ui.message(this,region==null?"전체 조회 오류":"조회 오류",detail==null?"조회 목록을 준비하지 못했습니다.":detail);}
 void launchCollection(Intent next,String region){try{startActivity(next);}catch(Exception e){String detail=e.getMessage();collectionPlanningFailed(region,detail==null||detail.isEmpty()?"조회 화면을 열지 못했습니다. 다시 시도해 주세요.":detail);}}
 void startCollection(String region){
  if(planningClosed||isDestroyed()||isFinishing())return;
  if(!BuildConfig.SCANNER){openScanner();return;}
  final boolean oz=isAsiana();
  if(CollectionService.active(oz)!=null){Toast.makeText(this,"이미 조회가 진행 중입니다.",Toast.LENGTH_SHORT).show();launchCollection(new Intent(this,CollectActivity.class).putExtra("oz",oz),region);return;}
  if(preparingCollection){Toast.makeText(this,"조회 목록을 준비 중입니다. 잠시 기다려 주세요.",Toast.LENGTH_SHORT).show();return;}
  final CollectionPlan plan;try{plan=snapshotCollectionPlan(region);}catch(Exception e){collectionPlanningFailed(region,e.getMessage());return;}
  preparingCollection=true;preparingRegion=region;final int generation=++planningGeneration;collectionPreparingUi();
  try{planningWorker.execute(()->{
   ArrayList<String> keys=new ArrayList<>();String error=null;
   try{if(planningClosed||Thread.currentThread().isInterrupted())return;JSONArray batches=buildCollectionPlan(plan);if(planningClosed||Thread.currentThread().isInterrupted())return;if(batches.length()>0)saveBatches(batches);for(int i=0;i<batches.length();i++)keys.add(batches.getJSONObject(i).getString("key"));}
   catch(Exception e){error=e.getMessage();if(error==null||error.isEmpty())error="조회 목록을 준비하지 못했습니다. 다시 시도해 주세요.";}
   if(planningClosed||Thread.currentThread().isInterrupted())return;final String problem=error;final ArrayList<String> preparedKeys=keys;
   remoteHandler.post(()->{if(planningClosed||isDestroyed()||isFinishing()||generation!=planningGeneration)return;preparingCollection=false;preparingRegion=null;collectionPreparingUi();if(problem!=null){collectionPlanningFailed(region,problem);return;}if(preparedKeys.isEmpty()){Ui.message(this,"조회 대상 없음","현재 기준 공항에서 조회 가능한 노선이 없습니다. 저장된 달력은 도시 목록에서 확인할 수 있습니다.");return;}
    if(CollectionService.active(plan.asiana)!=null){launchCollection(new Intent(this,CollectActivity.class).putExtra("oz",plan.asiana),region);return;}
    Intent next=new Intent(this,CollectActivity.class).putExtra("oz",plan.asiana).putExtra("batchKey",preparedKeys.get(0)).putExtra("shared",true);if(region==null)next.putStringArrayListExtra("allBatchKeys",preparedKeys);launchCollection(next,region);
   });
  });}catch(java.util.concurrent.RejectedExecutionException e){if(!planningClosed&&!isDestroyed()){preparingCollection=false;preparingRegion=null;collectionPreparingUi();collectionPlanningFailed(region,"조회 목록 준비를 시작하지 못했습니다.");}}
 }
 boolean booting=false;int bootPercent=0;TextView bootStatus,bootNumber;ProgressBar bootProgress;LinearLayout bootRoot;AlertDialog startupNotice;TextView remoteStatus;boolean syncing=false;final android.os.Handler remoteHandler=new android.os.Handler(android.os.Looper.getMainLooper());long lastSyncAttempt=0;final java.util.concurrent.ExecutorService remoteWorker=java.util.concurrent.Executors.newSingleThreadExecutor();Button batchOrigin;SkyDb db;LinearLayout content;android.content.SharedPreferences prefs;final List<String> airports=new ArrayList<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);SkyLocale.apply(this);if(!isAsiana())TimetableReference.load(this);db=new SkyDb(this,isAsiana());remoteWorker.execute(()->{try(ScanJournal log=new ScanJournal(this)){try{CrashCapture.importPending(this,log);}catch(Exception ignored){}log.recoverInterrupted();log.importLegacy(db);}catch(Exception ignored){/* Service/status and history screen expose write/read errors. */}});prefs=getSharedPreferences(isAsiana()?"settings-asiana":"settings",MODE_PRIVATE);ReminderJob.schedule(this,false);try(java.io.BufferedReader r=new java.io.BufferedReader(new java.io.InputStreamReader(getAssets().open("airports.txt")))){String s;while((s=r.readLine())!=null)airports.add(s);}catch(Exception e){throw new IllegalStateException(e);}if(!isAsiana()&&!prefs.getBoolean("testOffline",false))startLoading();else enterMain();}
