 ScrollView dashboardScroll;DashboardStats dashboardStats=new DashboardStats();String statsOrigin="";volatile int dashboardGeneration=0;boolean dashboardRefreshPending=false;
 void render(){if(booting||db==null||isDestroyed())return;String anchor=prefs.getString("departure","ICN 서울 인천").substring(0,3);if(!anchor.equals(statsOrigin)){dashboardStats=new DashboardStats();statsOrigin=anchor;}Dashboard.build(this,dashboardStats);decorateRepeatRules();collectionPreparingUi();int generation=++dashboardGeneration;remoteWorker.execute(()->{if(generation!=dashboardGeneration||Thread.currentThread().isInterrupted())return;try{DashboardStats next=DashboardStats.load(this,anchor,isAsiana());remoteHandler.post(()->{if(isDestroyed()||generation!=dashboardGeneration)return;dashboardStats=next;dashboardRefreshPending=true;applyDashboardStats();});}catch(Exception ignored){}});}
