 void githubConnection(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(Ui.dp(this,20),0,Ui.dp(this,20),0);form.addView(Ui.text(this,carrierName()+" 조회는 이 휴대폰에서 진행합니다. GitHub는 결과를 다른 기기와 공유하는 저장 공간입니다. 공유 결과 읽기는 연결 없이 가능합니다. 새 결과를 GitHub에 저장할 휴대폰은 한 번 연결하세요.\n\nGitHub에서 Fine-grained token을 만들고 bong40101-prog/tong-sky-data 저장소만 선택한 뒤 Contents를 Read and write로 설정하세요. 저장소 소유자 또는 쓰기 권한이 있는 계정이 필요합니다. 토큰은 이 폰에 암호화해 보관하며 APK·공유 달력에 포함하지 않습니다.",14));EditText input=new EditText(this);input.setSingleLine(true);input.setHint("GitHub 토큰 · 빈칸으로 저장하면 연결 해제");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);form.addView(input);form.addView(Ui.button(this,"GitHub 연결 키 만들기",v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/settings/personal-access-tokens/new")))));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("GitHub 저장 연결").setView(form).setNegativeButton("취소",null).setPositiveButton("저장",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=input.getText().toString().trim();Button save=dialog.getButton(AlertDialog.BUTTON_POSITIVE);save.setEnabled(false);save.setText("연결 확인 중…");input.setError(null);remoteWorker.execute(()->{String error=null;try{if(!value.isEmpty())new GitHubStore("ICN","europe",value).verifyConnection();GitHubToken.save(this,value);}catch(Exception e){error=e.getMessage();}final String result=error;remoteHandler.post(()->{if(isDestroyed()||!dialog.isShowing())return;save.setEnabled(true);save.setText("저장");if(result!=null){input.setError(result);return;}input.getText().clear();dialog.dismiss();Toast.makeText(this,value.isEmpty()?"저장 연결을 해제했습니다.":"읽기 연결을 확인하고 저장했습니다. 저장 권한은 조회 시작 전에 확인합니다.",Toast.LENGTH_LONG).show();});});}));dialog.show();}
